UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, "rb") as f:
        raw = f.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    return raw.decode("utf-8-sig")


def lines_of(text):
    for ln in text.split("\n"):
        if ln.endswith("\r"):
            ln = ln[:-1]
        if ln.strip():
            yield ln


def to_epoch(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_epoch(naive, zone, prefer_dst=None):
    """Naive local time -> epoch. prefer_dst: True/False picks among repeated times; None -> first."""
    cands = []
    for fold in (0, 1):
        d = naive.replace(tzinfo=zone, fold=fold)
        rt = datetime.fromtimestamp(to_epoch(d), UTC).astimezone(zone).replace(tzinfo=None)
        if rt == naive:
            cands.append(d)
    if not cands:  # nonexistent time: use fold 0 interpretation
        return to_epoch(naive.replace(tzinfo=zone))
    if len(cands) == 1 or to_epoch(cands[0]) == to_epoch(cands[1]):
        return to_epoch(cands[0])
    if prefer_dst is None:
        return to_epoch(cands[0])
    for d in cands:
        if bool(d.dst()) == prefer_dst:
            return to_epoch(d)
    return to_epoch(cands[0])


def std_offset(zone, year):
    offs = []
    for m in (1, 7):
        offs.append(zone.utcoffset(datetime(year, m, 1)))
    return min(offs)


