def parse_abbr(text, zone):
    header = None
    for ln in lines_of(text):
        row = next(csv.reader([ln]))
        row = [c.strip() for c in row]
        if "Badge" in row and "Punch" in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        mo, d, y = r["Date"].split("/")
        t = r["Time"].strip()
        ampm = None
        if t.upper().endswith("AM") or t.upper().endswith("PM"):
            ampm = t[-2:].upper()
            t = t[:-2].strip()
        h, mi, s = [int(x) for x in t.split(":")]
        if ampm:
            h = h % 12 + (12 if ampm == "PM" else 0)
        naive = datetime(int(y), int(mo), int(d), h, mi, s)
        ab = r.get("Zone", "").strip().upper()
        pd = True if ab.endswith("DT") else (False if ab.endswith("ST") else None)
        yield r["Record"], r["Badge"], r["Punch"].upper(), local_to_epoch(naive, zone, pd)


