    for ln in lines_of(text):
        o = json.loads(ln)
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            pid, emp, dr, ms = o["punch_id"], o["employee"], o["direction"], o["epoch_ms"]
            ts = int(ms) // 1000
        else:
            pid, emp, dr = o["id"], o["emp"], o["dir"]
            if "ts_ms" in o:
                ts = int(o["ts_ms"]) // 1000
            else:
                ts = int(o["ts"])
        yield str(pid), emp, dr.upper(), ts


def parse_offset(text, zone):
    rd = csv.reader(io.StringIO("\n".join(lines_of(text))), delimiter=";", quotechar='"')
    header = None
    for row in rd:
        if not row:
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        r = dict(zip(header, row))
        ts = r["timestamp"].strip()
        dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        d = "IN" if r["event"].strip() == "clock_in" else "OUT"
        yield r["punch_id"], r["employee"], d, to_epoch(dt)


def parse_legacy(text, zone):
    off = None
    for ln in lines_of(text):
        c = ln[0]
        if c == "H":
            tail = ln[13:18].strip()
            if len(tail) == 5 and tail[0] in "+-":
                sec = (int(tail[1:3]) * 60 + int(tail[3:5])) * 60
                off = timedelta(seconds=-sec if tail[0] == "-" else sec)
            else:
                off = None
        elif c == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = "IN" if ln[15] == "I" else "OUT"
            ts = ln[16:30]
            naive = datetime(int(ts[0:4]), int(ts[4:6]), int(ts[6:8]), int(ts[8:10]), int(ts[10:12]), int(ts[12:14]))
            o = off if off is not None else std_offset(zone, naive.year)
            yield pid, "E" + badge, d, to_epoch(naive.replace(tzinfo=UTC) - o)


def parse_de(text, zone):
