        if "Ausweis" in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        dd, mm, yy = r["Datum"].split(".")
        hh, mi = r["Uhrzeit"].split(":")[:2]
        naive = datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
        z = r.get("Zeitzone", "").upper()
        pd = True if z == "MESZ" else (False if z == "MEZ" else None)
        yield r["Nr"], r["Ausweis"], "IN" if r["Buchung"] == "K" else "OUT", local_to_epoch(naive, zone, pd)


