                        punches[key] = [str(emp).strip(), dr, ts]

    # 2. corrections
    corrs = []
    cdir = os.path.join(inp, "corrections")
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                for r in read_csv_file(os.path.join(root, fn)):
                    r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                    corrs.append(r)
    corrs.sort(key=lambda r: (to_epoch(parse_iso(r["issued_at"])), r["correction_id"]))
    applied = 0
    for r in corrs:
        if to_epoch(parse_iso(r["issued_at"])) > cutoff:
            continue
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = to_epoch(parse_iso(r["time"]))
                applied += 1
        elif act == "add":
            if key not in ever and r["site"] in sites:
                ever.add(key)
                punches[key] = [r["employee"], r["type"].upper(), to_epoch(parse_iso(r["time"]))]
                applied += 1

    # group, discard unknown badges
    per = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            per.setdefault(emp, []).append((ts, 0 if dr == "OUT" else 1, site, pid, dr))

    def rnd(ts, zone):
        off = int(zone.utcoffset(datetime.fromtimestamp(ts, UTC).replace(tzinfo=None)) .total_seconds()) \
            if False else int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
        loc = ts + off
        return (loc + 180) // 360 * 360 - off

    ex = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0, "corrections_applied": applied}
    result = {}
    off_cache = {}

    def offset_at(zone, ts):
        k = (zone.key, ts // 900)
        if k not in off_cache:
            off_cache[k] = int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
        return off_cache[k]

    def workday(ts, hz):
        return (datetime.fromtimestamp(ts, UTC).astimezone(hz)).date()

    for emp in employees:
        hz = sites[employees[emp]][0] if employees[emp] in sites else UTC
        pl = sorted(per.get(emp, []), key=lambda p: (p[0], p[1], p[2], p[3]))
        kept = []
        last = None
        for ts, _, site, pid, dr in pl:
            r = rnd(ts, sites[site][0])
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                if pstart <= workday(r, hz) <= pend:
                    ex["duplicates_dropped"] += 1
                continue
            p = (ts, 0, site, pid, dr, r)
            kept.append(p)
            last = p
        shifts = []
        cur = None
        for p in kept:
            if p[4] == "IN":
                if cur is not None and pstart <= workday(cur[5], hz) <= pend:
                    ex["open_shifts"] += 1
                cur = p
            else:
                if cur is not None and p[5] - cur[5] <= 16 * 3600:
                    shifts.append((cur, p))
                    cur = None
                else:
                    if cur is not None:
                        if pstart <= workday(cur[5], hz) <= pend:
                            ex["open_shifts"] += 1
                        cur = None
                    if pstart <= workday(p[5], hz) <= pend:
                        ex["orphan_outs"] += 1
        if cur is not None and pstart <= workday(cur[5], hz) <= pend:
            ex["open_shifts"] += 1

        rows = []
        for i, o in shifts:
            wd = workday(i[5], hz)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (o[5] - i[5]) // 60)
            paid = worked - 30 if worked > 360 else worked
            zone = sites[i[2]][0]
            night = 0
            t = i[5]
            while t < o[5]:
                mod = ((t + offset_at(zone, t)) // 60) % 1440
                if mod < 360 or mod >= 1320:
                    night += 1
                t += 60
            night = min(night, paid)
            rows.append([i[5], wd, paid, night])
        rows.sort(key=lambda r: r[0])
        day_acc, week_acc = {}, {}
        gross = Fraction(0)
        tot_paid = tot_ot = tot_night = 0
        for ts, wd, paid, night in rows:
            before = day_acc.get(wd, 0)
            day_acc[wd] = before + paid
            dot = max(0, before + paid - 480) - max(0, before - 480)
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = week_acc.get(wk, 0)
            week_acc[wk] = wb + nd
            wot = max(0, wb + nd - 2400) - max(0, wb - 2400)
            ot = dot + wot
            reg = paid - ot
            rl = rates.get(emp, [])
            rate = Fraction(0)
            if rl:
                rate = rl[0][1]
                for ef, rt in rl:
                    if ef <= wd:
                        rate = rt
            gross += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            tot_paid += paid
            tot_ot += ot
            tot_night += night
        cents = (gross * 100 + Fraction(1, 2)).__floor__()
        result[emp] = {"shifts": len(rows), "paid_minutes": tot_paid, "overtime_minutes": tot_ot,
                       "night_minutes": tot_night, "cents": cents}

    emps_out = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tc = 0
    fmt = lambda c: "%d.%02d" % divmod(c, 100)
    for emp, v in result.items():
        emps_out[emp] = {k: v[k] for k in tot}
        emps_out[emp]["gross"] = fmt(v["cents"])
        for k in tot:
            tot[k] += v[k]
        tc += v["cents"]
    tot["gross"] = fmt(tc)
    out = {"period": {"start": period["start"], "end": period["end"]}, "employees": emps_out,
           "exceptions": ex, "totals": tot}
    with open(outp, "w") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
